import java.util.regex.Pattern; public final class RegexAudit {static String hex(String s){StringBuilder b=new StringBuilder();for(int i=0;i<s.length();i++){if(i>0)b.append(',');b.append(Integer.toHexString(s.charAt(i)));}return b.toString();}public static void main(String[] args){String[] ps={"^+","^*","^?","^+$","[^\n]+$","^[^\n]+$","[x\r]+$","^x\r$","^x$","^$","$","^a+$"};String[] ts={"","x\r\n","x\n","\r\n","aaa\r\n"};for(String p:ps)for(String t:ts){String id=hex(p)+"/"+hex(t);try{Pattern q=Pattern.compile(p);System.out.println(id+"="+q.matcher(t).matches()+"/"+hex(q.matcher(t).replaceAll("X")));}catch(Throwable e){System.out.println(id+"=EX:"+e.getClass().getName());}}}}